  --line: #23262d;
  --fg: #e6e8eb;
  --dim: #8b919b;
  --accent: #7cc4ff;
}
* { box-sizing: border-box; }
html, body { margin: 0; background: var(--bg); color: var(--fg); }
body { font-family: var(--font-inter), system-ui, sans-serif; line-height: 1.55; -webkit-font-smoothing: antialiased; }
a { color: var(--accent); }
.top { padding: 16px 20px; border-bottom: 1px solid var(--line); }
.brand { font-family: var(--font-mono), monospace; color: var(--fg); text-decoration: none; font-weight: 600; }
main { max-width: 1100px; margin: 0 auto; padding: 32px 20px 64px; }
h1 { font-size: clamp(1.6rem, 5vw, 2.4rem); line-height: 1.2; margin: 0 0 16px; letter-spacing: -0.02em; }
.lede { color: var(--dim); max-width: 60ch; font-size: 1.05rem; }
.meta { color: var(--dim); font-size: 0.85rem; margin: 0 0 20px; }
.banner { border: 1px solid var(--line); background: var(--panel); border-radius: 8px; padding: 12px 16px; color: var(--dim); margin: 16px 0; }
.empty { border: 1px dashed var(--line); border-radius: 8px; padding: 32px 20px; text-align: center; color: var(--dim); }
.scroll { overflow-x: auto; border: 1px solid var(--line); border-radius: 8px; background: var(--panel); }
table { border-collapse: collapse; width: 100%; min-width: 880px; font-size: 0.9rem; }
th, td { padding: 10px 12px; text-align: right; white-space: nowrap; border-bottom: 1px solid var(--line); }
th { color: var(--dim); font-weight: 500; font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.04em; }
tr:last-child td { border-bottom: 0; }
th:first-child, td:first-child { text-align: left; }
td.num { font-family: var(--font-mono), monospace; }
.na { color: var(--dim); }
.sub { display: block; color: var(--dim); font-size: 0.75rem; font-family: var(--font-mono), monospace; }
.badge { display: inline-block; font-family: var(--font-mono), monospace; font-size: 0.75rem; padding: 2px 8px; border: 1px solid var(--line); border-radius: 999px; color: var(--accent); }
.skel { display: block; height: 14px; border-radius: 4px; background: linear-gradient(90deg, var(--line), #2c3038, var(--line)); background-size: 200% 100%; animation: sh 1.4s infinite; }
@keyframes sh { to { background-position: -200% 0; } }
@media (max-width: 600px) { main { padding: 20px 14px 48px; } }

